def transform(grid):
    h = len(grid)
    out = [[0] * 7 for _ in range(h)]

    marker_col = next(c for row in grid for c, v in enumerate(row) if v == 5)
    x = marker_col - 8
    if 0 <= x < 7:
        out[0][x] = 5
    y = 1

    signatures = {
        # Motif, horizontal displacement, stroke length, vertical height
        frozenset({(0,0), (0,1), (1,0), (1,2), (2,1)}): (2, 3, 1),
        frozenset({(0,0), (0,2), (1,0), (1,2), (2,0), (2,1), (2,2)}): (-1, 2, 1),
        frozenset({(0,0), (0,2), (1,1), (2,1)}): (0, 1, 2),
        frozenset({(0,0), (0,1), (0,2), (1,1), (2,0), (2,2)}): (-3, 4, 1),
    }

    # Read the tiles down the left column, then down the right column.
    for left in (0, 4):
        for top in range(0, h - 2, 4):
            cells = [(r, c) for r in range(3) for c in range(3)
                     if grid[top + r][left + c] not in (0, 4, 5)]
            if not cells:
                continue

            color = grid[top + cells[0][0]][left + cells[0][1]]
            signature = frozenset(cells)
            dx, length, height = signatures[signature]
            new_x = x + dx

            if dx == 0:
                for rr in range(y, min(h, y + height)):
                    if 0 <= new_x < 7:
                        out[rr][new_x] = color
            else:
                for c in range(min(x, new_x), max(x, new_x) + 1):
                    if 0 <= c < 7 and y < h:
                        out[y][c] = color

            x = new_x
            y += height

    return out
